script:
(function(){var f=document.getElementById('lead'),l=document.getElementById('f-link'),m=document.getElementById('f-msg');
f.addEventListener('submit',function(e){e.preventDefault();
var g=function(id){return (document.getElementById(id).value||'').trim();};
if(!g('f-nome')||!g('f-tel')){m.textContent='Preencha nome e WhatsApp para continuar.';return;}
var t='Olá! Sou '+g('f-nome')+' ('+g('f-tel')+'). Tipo de negócio: '+g('f-tipo')+'. Situação: '+g('f-sit')+'. Local: '+(g('f-end')||'não informado')+'. Prazo: '+g('f-prazo')+'.'+(g('f-cnae')?' CNAE/CNPJ: '+g('f-cnae')+'.':'');
var u='https://wa.me/5511942232969?text='+encodeURIComponent(t);
l.href=u;l.hidden=false;m.textContent='Mensagem pronta. Se o WhatsApp não abriu, toque em “Abrir a mensagem no WhatsApp”.';
try{window.open(u,'_blank','noopener');}catch(err){}
});})();
